"""Check every witness in libraries generated by library.py, without checksums."""
from ..runtime import run as _run, fail as _fail
import argparse
import json
import struct
import time
from pathlib import Path
from ..model import D, PI, gate, expression

def audit(folder):
    cutoff = int(folder.name)
    inp = folder / 'input.bin'
    inputs = []
    if inp.exists():
        with inp.open('rb') as f:
            count, = struct.unpack('<I', f.read(4))
            for _ in range(count):
                inputs.append(struct.unpack('<QI', f.read(12)))
            assert not f.read(1)
    rows = 0
    names = list(D)
    with (folder / 'image.bin').open('rb') as f:
        found, count = struct.unpack('<II', f.read(8))
        assert found == 0
        while (block := f.read(32 * 65536)):
            assert len(block) % 32 == 0
            for truth, arrival, kind, a, b, c, d in struct.iter_unpack('<Qiiiiii', block):
                if kind == -2:
                    expected, timing = expression([names[b], f'x{a}'])
                    assert names[b] in ('BUF', 'INV') and 0 <= a < 6
                elif kind == -1:
                    assert 0 <= a < len(inputs)
                    expected, timing = inputs[a]
                else:
                    from ..model import ARITY
                    assert 0 <= kind < len(names)
                    g = names[kind]
                    ids = (a, b, c, d)[:ARITY[g]]
                    assert all((0 <= i < len(inputs) for i in ids))
                    terms = [inputs[i] for i in ids]
                    expected = gate(g, [p[0] for p in terms])
                    timing = max((p[1] for p in terms)) + D[g]
                assert truth == expected and arrival == timing and (arrival <= cutoff)
                rows += 1
        assert rows == count
    return dict(bound_fs=cutoff, checked_rows=rows, status='ALL_WITNESSES_VALID')

def main():
    ap = argparse.ArgumentParser(description=__doc__)
    ap.add_argument('directory', type=Path)
    a = ap.parse_args()
    start = time.time()
    rows = [audit(p) for p in sorted(a.directory.iterdir()) if p.is_dir() and p.name.isdigit()]
    assert rows, 'No generated library stages found'
    report = dict(status='PASS', stages=rows, seconds=time.time() - start, scope='Witness validity; completeness additionally relies on the exhaustive-loop induction.')
    (a.directory / 'witness_audit.json').write_text(json.dumps(report, indent=2), encoding='utf-8')
    print(json.dumps(report, indent=2))
if __name__ == '__main__':
    try:
        main()
    except Exception as error:
        _fail(error)
